{% extends 'eshop/base.html' %}
{% load static %}
{% block title %}Sản phẩm{% endblock %}

{% block content %}

<div class="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 lg:grid-cols-4 gap-8">

    <!-- Sidebar: Categories -->
    <aside class="bg-white rounded-2xl shadow p-6 hidden lg:block">
        <h3 class="text-lg font-semibold mb-4">Danh mục</h3>
        <ul class="space-y-2">
            {% for category in categories %}
            <li>
                <a href="{% url 'eshop:products' %}?category={{ category.slug }}"
                   class="block px-4 py-2 rounded-lg hover:bg-blue-50 hover:text-blue-600 transition {% if current_category == category.slug %}bg-blue-100 text-blue-600 font-semibold{% endif %}">
                    {{ category.name }}
                </a>
            </li>
            {% endfor %}
        </ul>
    </aside>

    <!-- Main content -->
    <div class="lg:col-span-3 space-y-6">

        <!-- Search bar -->
        <form method="get" class="flex gap-2 justify-end">
            <input type="text" name="q" value="{{ query }}" placeholder="Tìm sản phẩm..."
                   class="border rounded-full px-4 py-2 flex-1 focus:outline-none focus:ring-2 focus:ring-blue-500">
            <button type="submit" class="bg-blue-600 text-white px-4 py-2 rounded-full hover:bg-blue-700 transition">
                <i class="fas fa-search"></i>
            </button>
        </form>

        <!-- Products grid -->
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {% for product in products %}
            {% include 'eshop/_product_card.html' %}
            {% empty %}
            <p class="text-gray-500 col-span-full text-center">Chưa có sản phẩm nào.</p>
            {% endfor %}
        </div>

        <!-- Pagination -->
        {% if products.has_other_pages %}
        <div class="flex justify-center mt-6 space-x-2">
            {% if products.has_previous %}
            <a href="?page={{ products.previous_page_number }}" class="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300 transition">← Trước</a>
            {% endif %}
            {% for num in products.paginator.page_range %}
                {% if products.number == num %}
                <span class="px-3 py-1 bg-blue-600 text-white rounded">{{ num }}</span>
                {% else %}
                <a href="?page={{ num }}" class="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300 transition">{{ num }}</a>
                {% endif %}
            {% endfor %}
            {% if products.has_next %}
            <a href="?page={{ products.next_page_number }}" class="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300 transition">Sau →</a>
            {% endif %}
        </div>
        {% endif %}

    </div>
</div>

{% endblock %}
